import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE 32

__global__ void triu_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    int bi = blockIdx.y;
    int bj = blockIdx.x;

    // Skip blocks that are entirely in the strictly-lower part of the output.
    if (bi > bj) return;

    // Wrap global memory in CuTe tensors.
    Tensor gA = make_tensor(make_gmem_ptr(A), make_shape(N, N), make_stride(N, Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(N, N), make_stride(N, Int<1>{}));
    Tensor gC = make_tensor(make_gmem_ptr(C), make_shape(N, N), make_stride(N, Int<1>{}));

    int tx = threadIdx.x; // column within tile
    int ty = threadIdx.y; // row within tile

    int row = bi * TILE + ty;
    int col = bj * TILE + tx;

    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    float acc = 0.f;

    // Because A is upper triangular, only k >= row's block start (bi*TILE) matters.
    // Because B is upper triangular, only k <= col's block end ((bj+1)*TILE - 1) matters.
    int k_start = bi * TILE;
    int k_end   = (bj + 1) * TILE; // exclusive

    for (int kb = k_start; kb < k_end; kb += TILE) {
        int a_row = row;
        int a_col = kb + tx;
        As[ty][tx] = (a_row < N && a_col < N) ? gA(a_row, a_col) : 0.f;

        int b_row = kb + ty;
        int b_col = col;
        Bs[ty][tx] = (b_row < N && b_col < N) ? gB(b_row, b_col) : 0.f;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        if (bi == bj && row > col) {
            acc = 0.f; // mask strictly-lower part of the diagonal block
        }
        gC(row, col) = acc;
    }
}

torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have the same size");

    int N = (int)A.size(0);

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C = torch::zeros({N, N}, A.options());

    int num_tiles = (N + TILE - 1) / TILE;

    dim3 block(TILE, TILE);
    dim3 grid(num_tiles, num_tiles); // grid.x -> bj, grid.y -> bi

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    triu_matmul_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), N);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE triu matmul launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for upper
    triangular matrices using a custom CuTe/CUDA kernel that exploits the
    triangular structure of A and B to skip unnecessary work.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_triu_matmul(A, B)

